import{_ as c,o as a,c as o,a3 as n}from"./chunks/framework.DAK02U1-.js";const h=JSON.parse('{"title":"编译命令","description":"clice command 显示 clice 编译文件时使用的命令，也可将编译命令转换为这种形式供其他工具读取。它读取编译数据库并向其中指定的编译器查询，既不需要索引，也不需要服务器。","frontmatter":{"head":[["meta",{"property":"og:title","content":"编译命令 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/command"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/command"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/command"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/command"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/command"}],["meta",{"property":"og:description","content":"clice command 显示 clice 编译文件时使用的命令，也可将编译命令转换为这种形式供其他工具读取。它读取编译数据库并向其中指定的编译器查询，既不需要索引，也不需要服务器。"}]]},"headers":[],"relativePath":"zh/clice/cli/command.md","filePath":"zh/clice/cli/command.md","lastUpdated":1794738697000}'),i={name:"zh/clice/cli/command.md"};function s(l,e,t,d,r,m){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="command" tabindex="-1"><span id="编译命令" class="heading-alias"></span>编译命令 <a class="header-anchor" href="#command" aria-label="Permalink to &quot;编译命令&quot;">​</a></h1><h2 id="overview" tabindex="-1"><span id="概述" class="heading-alias"></span>概述 <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>clice command</code> 显示 clice 编译文件时使用的命令，也可将编译命令转换为这种形式供其他工具读取。它读取编译数据库并向其中指定的编译器查询，既不需要索引，也不需要服务器。</p><p><strong>用法</strong>：<code>clice command &lt;file&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--json]</code></p><p><strong>用法</strong>：<code>clice command convert &lt;compile_commands.json&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;]</code></p><p><strong>用法</strong>：<code>clice command convert [--json] [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] -- &lt;compiler&gt; &lt;arguments&gt;...</code></p><h2 id="a-file-s-commands" tabindex="-1"><span id="文件的编译命令" class="heading-alias"></span>文件的编译命令 <a class="header-anchor" href="#a-file-s-commands" aria-label="Permalink to &quot;文件的编译命令&quot;">​</a></h2><p><code>clice command &lt;file&gt;</code> 按构建给出的优先级顺序列出各编译数据库中该文件的所有条目；用户另选之前，编辑器使用排在第一位的条目编译该文件。每个条目会显示所属数据库、条目原文（<code>command</code> 字符串按 clice 的拆分方式展开），以及 clice 按该条目编译文件时实际使用的命令：先按<a href="./../guide/configuration#rules">规则</a>（定义于 <code>clice.toml</code>）编辑条目，再交给条目指定的编译器解析，将目标平台与系统头文件目录补全为一条 <code>-cc1</code> 命令的参数。若其中某些目录含有 clice 编译时不可见的文件——被 clang 自身内置头文件替代的其他编译器内置头文件（GCC 私有目录中的头文件，或另一个 clang 的内置头文件），以及列表中位置更靠后、原编译器也永远不会读到的同名文件——每个这类目录都会附一行 <code>hidden</code> 统计其数量（参见<a href="./../design/command-resolve#asking-the-compiler">查询编译器</a>）。若因编译器未安装或拒绝查询而无法查询，错误信息会说明原因，显示的命令则改为 clang 自身驱动代替该编译器读取的驱动命令，与规则设有 <code>query_toolchain = false</code> 时一致；基于兼容版本 Clang 构建的工具读取该命令的结果与 clice 相同。<code>--json</code> 将相同内容输出为单个 JSON 对象。</p><p>所读取的编译数据库与编辑器为该文件加载的一致：优先使用规则指定的数据库；未指定时，则是项目根目录、其直接子目录，以及从该文件到根目录之间各级目录中的 <code>compile_commands.json</code>；带有自身 <code>clice.toml</code> 或 <code>.clice/config.toml</code> 的目录及其下所有内容属于另一个项目。本身没有条目的文件（例如头文件，编辑器会借用包含它的源文件的命令来编译）会报告为没有条目。</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ clice command src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">/home/me/project/build/compile_commands.json:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  directory: /home/me/project/build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  command:   /usr/bin/g++ -std=c++20 -O2 -Werror -o main.o -c ../src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  resolved:  /usr/bin/g++ -cc1 -main-file-name main.cpp -triple x86_64-unknown-linux-gnu -O2 … -internal-isystem /usr/include/c++/13 … -std=c++20 … -x c++ /home/me/project/src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  hidden:    112 of the files in /usr/lib/gcc/x86_64-linux-gnu/13/include</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">settings:  background_index = false (/home/me/project/clice.toml:6)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">           the rest by default</span></span></code></pre></div><p>条目之后，<code>settings</code> 列出各条<a href="./../guide/configuration#rules">规则</a>为该文件决定的设置——<code>background_index</code>、<code>skip_function_body</code>、<code>readonly</code>、<code>lint</code> 等按文件生效的字段——每项都会标明决定它的规则及其所在文件和起始行号；没有任何规则设置的字段取默认值。<code>--json</code> 会在 <code>settings</code> 下列出所有字段，给出各自的 <code>value</code>，若由某条规则决定则还会给出该 <code>rule</code>。</p><p>列出文件条目时退出码为 0；文件不存在或没有任何数据库列出该文件时为 1；读取期间数据库发生变化、参数无法解析，或项目及其配置无法加载时为 2。</p><h2 id="converting-commands" tabindex="-1"><span id="转换命令" class="heading-alias"></span>转换命令 <a class="header-anchor" href="#converting-commands" aria-label="Permalink to &quot;转换命令&quot;">​</a></h2><p><code>clice command convert &lt;compile_commands.json&gt;</code>（或传入包含该文件的目录）会输出整份数据库，并将每个条目的命令（<code>arguments</code> 或 <code>command</code>）替换为 clice 编译该条目文件时使用的 <code>arguments</code>（已应用项目 <code>clice.toml</code> 中的规则编辑）。条目保留 <code>file</code> 和 <code>output</code>；<code>directory</code> 转为绝对路径（原为相对路径时以数据库所在目录为基准）；其余字段一概略去。clice 不编译的条目（如汇编源文件）保留原命令。输出的命令会略去其他编译器的内置头文件目录，因为命令行无法表达其中被隐藏的文件（参见<a href="./../design/command-resolve#known-limitations">已知限制</a>）。<code>clice command convert -- &lt;compiler&gt; &lt;arguments&gt;...</code> 转换单条命令——该命令在当前目录下运行，且只编译一个 C 族源文件——默认输出为一行命令，加上 <code>--json</code> 时输出为单个数据库条目。</p><p>转换后的命令是构建 clice 所用 Clang 的 <code>-cc1</code> 命令，适用于基于兼容版本 Clang 构建的工具。编译器无法查询的命令则保持为驱动命令，即 clang 自身驱动代替该编译器读取的那条命令。</p><p>所有命令均转换成功时退出码为 0；有编译器无法查询时为 1，此时仍会先输出转换结果，其中无法查询的命令输出为上述驱动命令；数据库无法读取、单条命令未编译任何 C 族源文件或编译了多个源文件，或者参数无法解析时为 2。</p>`,16)])])}const g=c(i,[["render",s]]);export{h as __pageData,g as default};
